-- FAMILIEN-APP 1.0 — ausschliesslich fuer ein NEUES Supabase-Projekt
-- Im SQL Editor eines neuen Projekts einmalig ausfuehren.
create extension if not exists pgcrypto;
create table public.families (id uuid primary key default gen_random_uuid(), name text not null, created_by uuid not null references auth.users(id), created_at timestamptz default now());
create table public.members (family_id uuid not null references public.families(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, display_name text not null, can_approve boolean not null default false, can_delete_recipes boolean not null default false, is_admin boolean not null default false, joined_at timestamptz default now(), primary key(family_id,user_id));
create table public.invitations (id uuid primary key default gen_random_uuid(), family_id uuid not null references public.families(id) on delete cascade, token uuid not null unique default gen_random_uuid(), created_by uuid not null references auth.users(id), expires_at timestamptz not null default (now()+interval '14 days'), used_by uuid references auth.users(id), used_at timestamptz);
create table public.recipes (id uuid primary key default gen_random_uuid(), family_id uuid not null references public.families(id) on delete cascade, name text not null, servings numeric not null default 2 check(servings>0), instructions text not null default '', image_path text, created_by uuid not null references auth.users(id), created_at timestamptz not null default now());
create table public.ingredients (id uuid primary key default gen_random_uuid(), recipe_id uuid not null references public.recipes(id) on delete cascade, name text not null, amount numeric, unit text not null default '', category text not null default 'Sonstiges', pantry boolean not null default false, sort_order int not null default 0);
create table public.wishes (id uuid primary key default gen_random_uuid(), family_id uuid not null references public.families(id) on delete cascade, recipe_id uuid not null references public.recipes(id) on delete cascade, requested_by uuid not null references auth.users(id), status text not null default 'requested' check(status in ('requested','approved','cooked','cancelled')), portions numeric, planned_date date, created_at timestamptz not null default now());
create table public.shopping_items (id uuid primary key default gen_random_uuid(), family_id uuid not null references public.families(id) on delete cascade, wish_id uuid references public.wishes(id) on delete cascade, name text not null, amount numeric, unit text not null default '', category text not null default 'Sonstiges', purchased boolean not null default false, added_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.shopping_runs (id uuid primary key default gen_random_uuid(), family_id uuid not null references public.families(id) on delete cascade, finished_by uuid not null references auth.users(id), finished_at timestamptz not null default now(), purchased_count int not null default 0);
create index on public.members(user_id); create index on public.recipes(family_id); create index on public.wishes(family_id,status); create index on public.shopping_items(family_id,purchased);
create function public.is_member(fid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.members m where m.family_id=fid and m.user_id=(select auth.uid()))$$;
create function public.is_admin_member(fid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.members m where m.family_id=fid and m.user_id=(select auth.uid()) and m.is_admin)$$;
create function public.can_approve_member(fid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.members m where m.family_id=fid and m.user_id=(select auth.uid()) and (m.is_admin or m.can_approve))$$;
create function public.can_delete_member(fid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.members m where m.family_id=fid and m.user_id=(select auth.uid()) and (m.is_admin or m.can_delete_recipes))$$;
create function public.recipe_family(rid uuid) returns uuid language sql stable security definer set search_path='' as $$select family_id from public.recipes where id=rid$$;
create function public.wish_family(wid uuid) returns uuid language sql stable security definer set search_path='' as $$select family_id from public.wishes where id=wid$$;
create function public.create_family(family_name text, my_name text) returns uuid language plpgsql security definer set search_path='' as $$declare fid uuid; begin if auth.uid() is null then raise exception 'Nicht angemeldet'; end if; insert into public.families(name,created_by) values (left(trim(family_name),80),auth.uid()) returning id into fid; insert into public.members(family_id,user_id,display_name,is_admin,can_approve,can_delete_recipes) values(fid,auth.uid(),left(trim(my_name),80),true,true,true); return fid; end$$;
create function public.make_invitation(fid uuid) returns uuid language plpgsql security definer set search_path='' as $$declare t uuid;begin if not public.is_admin_member(fid) then raise exception 'Nur Admin';end if;insert into public.invitations(family_id,created_by) values(fid,auth.uid()) returning token into t;return t;end$$;
create function public.accept_invitation(invite_token uuid,my_name text) returns uuid language plpgsql security definer set search_path='' as $$declare inv public.invitations%rowtype;begin select * into inv from public.invitations where token=invite_token for update;if not found or inv.used_at is not null or inv.expires_at<now() then raise exception 'Einladung ungueltig oder abgelaufen';end if;if auth.uid() is null then raise exception 'Nicht angemeldet';end if;insert into public.members(family_id,user_id,display_name) values(inv.family_id,auth.uid(),left(trim(my_name),80)) on conflict(family_id,user_id) do nothing;update public.invitations set used_by=auth.uid(),used_at=now() where id=inv.id;return inv.family_id;end$$;
create function public.set_member_rights(fid uuid,target_uid uuid,approve boolean,delete_recipes boolean) returns void language plpgsql security definer set search_path='' as $$begin if not public.is_admin_member(fid) then raise exception 'Nur Admin';end if;update public.members set can_approve=approve,can_delete_recipes=delete_recipes where family_id=fid and user_id=target_uid and not is_admin;end$$;
create function public.approve_wish(wid uuid,people numeric) returns void language plpgsql security definer set search_path='' as $$declare w public.wishes%rowtype; r public.recipes%rowtype;begin select * into w from public.wishes where id=wid for update;if not found or w.status<>'requested' or not public.can_approve_member(w.family_id) then raise exception 'Freigabe nicht moeglich';end if;if people<=0 or people>100 then raise exception 'Ungueltige Portionenzahl';end if;select * into r from public.recipes where id=w.recipe_id;update public.wishes set status='approved',portions=people where id=wid;insert into public.shopping_items(family_id,wish_id,name,amount,unit,category,added_by) select w.family_id,wid,i.name,case when i.amount is null then null else round(i.amount*people/r.servings,3) end,i.unit,i.category,w.requested_by from public.ingredients i where i.recipe_id=r.id and not i.pantry and i.amount is not null and i.amount>0 and lower(trim(i.unit)) not in ('el','tl');end$$;
create function public.revoke_wish(wid uuid) returns void language plpgsql security definer set search_path='' as $$declare w public.wishes%rowtype;begin select * into w from public.wishes where id=wid for update;if not found or not public.can_approve_member(w.family_id) then raise exception 'Keine Berechtigung';end if;delete from public.shopping_items where wish_id=wid;update public.wishes set status='requested',portions=null,planned_date=null where id=wid;end$$;
create function public.finish_shopping(fid uuid) returns int language plpgsql security definer set search_path='' as $$declare n int;begin if not public.is_member(fid) then raise exception 'Kein Zugriff';end if;select count(*) into n from public.shopping_items where family_id=fid and purchased;insert into public.shopping_runs(family_id,finished_by,purchased_count) values(fid,auth.uid(),n);delete from public.shopping_items where family_id=fid and purchased;return n;end$$;
alter table public.families enable row level security;alter table public.members enable row level security;alter table public.invitations enable row level security;alter table public.recipes enable row level security;alter table public.ingredients enable row level security;alter table public.wishes enable row level security;alter table public.shopping_items enable row level security;alter table public.shopping_runs enable row level security;
create policy families_read on public.families for select to authenticated using(public.is_member(id));
create policy members_read on public.members for select to authenticated using(public.is_member(family_id));
create policy recipes_read on public.recipes for select to authenticated using(public.is_member(family_id));
create policy recipes_insert on public.recipes for insert to authenticated with check(public.is_member(family_id) and created_by=(select auth.uid()));
create policy recipes_update on public.recipes for update to authenticated using(public.is_member(family_id)) with check(public.is_member(family_id));
create policy recipes_delete on public.recipes for delete to authenticated using(public.can_delete_member(family_id));
create policy ingredients_read on public.ingredients for select to authenticated using(public.is_member(public.recipe_family(recipe_id)));
create policy ingredients_insert on public.ingredients for insert to authenticated with check(public.is_member(public.recipe_family(recipe_id)));
create policy ingredients_update on public.ingredients for update to authenticated using(public.is_member(public.recipe_family(recipe_id)));
create policy ingredients_delete on public.ingredients for delete to authenticated using(public.is_member(public.recipe_family(recipe_id)));
create policy wishes_read on public.wishes for select to authenticated using(public.is_member(family_id));
create policy wishes_insert on public.wishes for insert to authenticated with check(public.is_member(family_id) and requested_by=(select auth.uid()));
create policy wishes_update on public.wishes for update to authenticated using(public.is_member(family_id)) with check(public.is_member(family_id));
create policy wishes_delete on public.wishes for delete to authenticated using(public.is_member(family_id));
create policy shopping_read on public.shopping_items for select to authenticated using(public.is_member(family_id));
create policy shopping_insert on public.shopping_items for insert to authenticated with check(public.is_member(family_id) and wish_id is null and added_by=(select auth.uid()));
create policy shopping_update on public.shopping_items for update to authenticated using(public.is_member(family_id)) with check(public.is_member(family_id));
create policy shopping_delete on public.shopping_items for delete to authenticated using(public.is_member(family_id) and wish_id is null);
create policy runs_read on public.shopping_runs for select to authenticated using(public.is_member(family_id));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('recipe-images','recipe-images',false,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy image_read on storage.objects for select to authenticated using(bucket_id='recipe-images' and public.is_member((storage.foldername(name))[1]::uuid));
create policy image_insert on storage.objects for insert to authenticated with check(bucket_id='recipe-images' and public.is_member((storage.foldername(name))[1]::uuid));
create policy image_update on storage.objects for update to authenticated using(bucket_id='recipe-images' and public.is_member((storage.foldername(name))[1]::uuid)) with check(bucket_id='recipe-images' and public.is_member((storage.foldername(name))[1]::uuid));
create policy image_delete on storage.objects for delete to authenticated using(bucket_id='recipe-images' and public.can_delete_member((storage.foldername(name))[1]::uuid));
grant execute on function public.create_family(text,text),public.make_invitation(uuid),public.accept_invitation(uuid,text),public.set_member_rights(uuid,uuid,boolean,boolean),public.approve_wish(uuid,numeric),public.revoke_wish(uuid),public.finish_shopping(uuid) to authenticated;
-- Alle Statuswechsel erfolgen ausschliesslich ueber geschuetzte Funktionen.
drop policy wishes_update on public.wishes;
drop policy wishes_delete on public.wishes;
create function public.mark_cooked(wid uuid) returns void language plpgsql security definer set search_path='' as $$begin update public.wishes set status='cooked',planned_date=null where id=wid and status='approved' and public.is_member(family_id);if not found then raise exception 'Gericht nicht freigegeben';end if;end$$;
create function public.plan_wish(wid uuid,day date) returns void language plpgsql security definer set search_path='' as $$begin update public.wishes set planned_date=day where id=wid and status='approved' and public.is_member(family_id);if not found then raise exception 'Planung nicht moeglich';end if;end$$;
create function public.cancel_wish(wid uuid) returns void language plpgsql security definer set search_path='' as $$begin update public.wishes set status='cancelled' where id=wid and status='requested' and (requested_by=auth.uid() or public.can_approve_member(family_id));if not found then raise exception 'Wunsch nicht stornierbar';end if;end$$;
grant execute on function public.mark_cooked(uuid),public.plan_wish(uuid,date),public.cancel_wish(uuid) to authenticated;
